H.background();
const W = H.W, Hh = H.H;
const Ea = P.Ea;
const dH = -40;
const x0 = 90, x1 = W - 90;
const baseY = Hh - 120;
const kjToPx = 1.6;
const yReact = baseY;
const yProd = baseY + dH * kjToPx;
const yPeak = baseY - Ea * kjToPx;
const pts = [];
const N = 120;
for (let i = 0; i <= N; i++) {
  const f = i / N;
  const px = x0 + f * (x1 - x0);
  let py;
  if (f < 0.2) py = yReact;
  else if (f > 0.8) py = yProd;
  else {
    const u = (f - 0.2) / 0.6;
    const bump = Math.sin(Math.PI * u);
    const baseLine = yReact + (yProd - yReact) * u;
    py = baseLine - (baseLine - yPeak) * bump;
  }
  pts.push([px, py]);
}
